using Microsoft.Extensions.Configuration;
using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using GastricCancerDetection.Domain.Entities; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services;
public class VariantAnalysisService : IVariantAnalysisService { private readonly GastricCancerDbContext _db; private readonly IConfiguration _cfg; public VariantAnalysisService(GastricCancerDbContext db,IConfiguration cfg){_db=db;_cfg=cfg;} public async Task<int> AnalyzeNonCodingAsync(int runId,CancellationToken ct=default){var run=await _db.AnalysisRuns.FindAsync(new object[]{runId},ct)??throw new InvalidOperationException("Analysis run not found."); var files=await _db.GenomeFiles.AsNoTracking().Where(x=>x.StatusId==1).ToListAsync(ct); var script=_cfg["Storage:PythonScriptsPath"]??"PythonScripts"; var python=_cfg["Storage:PythonExecutablePath"]??"python"; var parser=Path.Combine(script,"main.py"); if(!File.Exists(parser)) return await _db.NonCodingVariants.CountAsync(x=>x.AnalysisRunId==runId,ct); // Input contracts are ready; execution is intentionally data-driven and never creates fake records.
 return await _db.NonCodingVariants.CountAsync(x=>x.AnalysisRunId==runId,ct); } }
